mapper.select:
SELECT f.id, f.user_id, f.sha256, f.storage_key, f.original_name,
       f.mime_type, f.extension, f.bytes, f.width, f.height, f.biz_type, f.created_at
FROM t_file f
WHERE f.user_id = #{userId}

  AND f.created_at <= #{before}
  AND NOT EXISTS (SELECT 1 FROM t_asset a WHERE a.file_id = f.id)
ORDER BY f.id
LIMIT #{limit}
